  }
  clearFilters(event) {
    if (event) {
      event.stopPropagation();
    }
    this.activeFilters = {
      company: null,
      members: [],
      dateRange: {
        from: undefined,
        to: undefined
      },
      unread: false,
      todo: false,
      attachments: false
    };
    this.filterMessages();
  }
  applyDetailFilters(filters) {
    this.activeFilters = filters;
    this.isFilterOpen = false;
    this.filterMessages();
  }
  filterMessages() {
    let result = this.messages;
    // Folder Filter
    if (this.selectedFolder !== 'All Folders') {
      result = result.filter(m => m.folder === this.selectedFolder);
    }
    // Search Filter
    if (this.searchQuery && this.searchQuery.trim()) {
      const query = this.searchQuery.toLowerCase();
      result = result.filter(m => {
        if ((m.sender || '').toLowerCase().includes(query)) return true;
        if ((m.subject || '').toLowerCase().includes(query)) return true;
        const conv = conversationsData[m.id];
        if (conv) {
          if ((conv.title || '').toLowerCase().includes(query)) return true;
          if (conv.messages.some(msg => (msg.content || '').toLowerCase().includes(query))) return true;
        }
        return false;
      });
    }
    // Advanced Filters
    if (this.activeFilters.company) {
      result = result.filter(m => m.companies.includes(this.activeFilters.company));
    }
    if (this.activeFilters.unread) {
      result = result.filter(m => m.unreadCount > 0);
    }
    if (this.activeFilters.todo) {
      result = result.filter(m => m.isTodo);
    }
    if (this.activeFilters.attachments) {
      result = result.filter(m => m.hasAttachment);
    }
    if (this.activeFilters.dateRange.from && this.activeFilters.dateRange.to) {
      result = result.filter(m => {
        if (!m.timestamp) return true;
        const msgDate = parseISO(m.timestamp);
        return isWithinInterval(msgDate, {
          start: startOfDay(this.activeFilters.dateRange.from),
          end: endOfDay(this.activeFilters.dateRange.to)
        });
      });
    }
    // Member filter would go here too
    this.filteredMessages = result;
  }
  handleSelectAll() {
    if (this.selectAll) {
      this.selectedItems.clear();
    } else {
      this.filteredMessages.forEach(m => this.selectedItems.add(m.id));
    }
    this.selectAll = !this.selectAll;
  }
  handleSelectItem(id) {
    if (this.selectedItems.has(id)) {
      this.selectedItems.delete(id);
    } else {
      this.selectedItems.add(id);
    }
    this.selectAll = this.selectedItems.size === this.filteredMessages.length;
  }
